/* interfaceMapper.updateInterfaceCnt  인터페이스 사용량(ORDER_CNT, DELIVERY_CODE_CNT) 업데이트 */	
	UPDATE TB_SMS_INTERFACE_INFO SET
	  
		ORDER_CNT = ISNULL(ORDER_CNT,0) + 1
	  
	  
	    DELIVERY_CODE_CNT = ISNULL(DELIVERY_CODE_CNT,0) + 1	
	  	
	WHERE 1 = 1  
	
	AND ENT_CODE = #{ReceiverId}
	
	AND CUSTOMER_CODE = #{SenderId}
	
	AND USE_YN = #{UseYN}

mapper.select:
	/* interfaceMapper.selectOrderTracking */
		
		SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,'' AS REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME
		FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_01 p ON od.OD_JOB_NO = p.OD_JOB_NO AND p.POD_STATUS NOT IN ('ECM060','ECM070') LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS  = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO'
		WHERE
		1=1 and sm.ETC16 = 'Y'
		
			
				
					
						
							and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
						
						
							and od.PO_NO = #{ordId}
						
						and BOUND = #{bound} and BOUND_TYPE = #{boundType}
					
					
						and od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND PO_NO = #{ordId} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType}
					
				
			
			
				
					and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
				
				
					and od.PO_NO = #{ordId}
				
			
		

		UNION ALL
		SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,'' AS REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME
		FROM TB_ECM_OD od
			 INNER JOIN TB_ECM_POD_01 p
			 			ON od.MASTER_OD_JOB_NO = p.OD_JOB_NO
			 			AND p.POD_STATUS IN ('ECM060','ECM070')
			 LEFT JOIN TB_SMS_CODE_DETAIL sm
			 		   ON p.POD_STATUS  = sm.CODE
			 		   AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO'
		WHERE
		1=1 and sm.ETC16 = 'Y'
		
			
				
					
						
							and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
						
						
							and od.PO_NO = #{ordId}
						
						and BOUND = #{bound} and BOUND_TYPE = #{boundType}
					
					
						and od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND PO_NO = #{ordId} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType}
					
				
			
			
				
					and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
				
				
					and od.PO_NO = #{ordId}
				
			
		
		UNION ALL
		SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,'' AS REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME
		FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_02 p ON od.OD_JOB_NO = p.OD_JOB_NO LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS  = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO'
		WHERE
		1=1 and sm.ETC16 = 'Y'
		
			
				
					
						
							and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
						
						
							and od.PO_NO = #{ordId}
						
						and BOUND = #{bound} and BOUND_TYPE = #{boundType}
					
					
						and od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND PO_NO = #{ordId} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType}
					
				
			
			
				
					and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
				
				
					and od.PO_NO = #{ordId}
				
			
		
		UNION ALL
		SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,p.REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME
		FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_03 p ON od.OD_JOB_NO = p.OD_JOB_NO LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS  = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO'
		WHERE
		1=1 and sm.ETC16 = 'Y'
		
			
				
					
						
							and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
						
						
							and od.PO_NO = #{ordId}
						
						and BOUND = #{bound} and BOUND_TYPE = #{boundType}
					
					
						and od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND PO_NO = #{ordId} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType}
					
				
			
			
				
					and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
				
				
					and od.PO_NO = #{ordId}
				
			
		
		UNION ALL
		SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME
			 , CASE WHEN p.POD_STATUS IN ('ECM361', 'ECM390', 'ECM420') THEN CONCAT(p.DELIVERY_STORE_NAME, '/', p.COURIER_NAME, '/', p.COURIER_TEL)
			        WHEN p.POD_STATUS = 'ECM400' 						THEN CONCAT(p.DELIVERY_STORE_NAME, '/', p.COURIER_NAME, '/', p.COURIER_TEL, '/', p.REMARKS)
			   ELSE p.REMARKS END AS REMARKS
			 ,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME
			 ,od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME
		FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_04 p ON od.OD_JOB_NO = p.OD_JOB_NO LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS  = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO'
		WHERE
		1=1 and sm.ETC16 = 'Y'
		
			
				
					
						
							and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
						
						
							and od.PO_NO = #{ordId}
						
							and BOUND = #{bound} and BOUND_TYPE = #{boundType}
					
					
						and od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND PO_NO = #{ordId} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType}
					
				
			
			
				
					and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
				
				
					and od.PO_NO = #{ordId}

/* interfaceMapper.selectDeliveryInterfaceApi */
SELECT
	 ENT_CODE
	,DELIVERY_CODE
	,RECV_API_URL
	,RECV_API_CODE
	,RECV_API_ID
	,RECV_API_PW
FROM TB_SMS_DELIVERY_API_INFO
WHERE ENT_CODE = #{entCode}
AND DELIVERY_CODE IN ('hms','cargo')

AND RECV_API_ID = #{recvApiId}


AND RECV_API_PW = #{recvApiPw}

mapper.insert:
/* interfaceMapper.insertPacking */

MERGE TB_ECM_OD_PACKING AS A
USING (SELECT #{OD_JOB_NO} AS OD_JOB_NO, #{item.packageNo} AS PACKING_NO) AS B
ON (A.OD_JOB_NO = B.OD_JOB_NO AND A.PACKING_NO = B.PACKING_NO)
WHEN NOT MATCHED BY TARGET THEN
INSERT (
	   OD_JOB_NO
	  ,SEQ_NO_ID
	  ,DELIVERY_NO
	  ,PACKING_NO
	  ,REGISTER_USER_ID
	  ,REGISTER_DATE_TIME
)VALUES(
	   
	   
	   #{OD_JOB_NO}
	   
	   
	   LTRIM(RTRIM(REPLACE(#{OD_JOB_NO},char(9),'')))
	   
	   
	  ,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_ECM_OD_PACKING WHERE OD_JOB_NO = #{OD_JOB_NO})
	  ,#{hblNo}
	  ,#{item.packageNo}
	  ,'API'
	  ,GETDATE()
);

