/* interfaceMapper.selectOrderTrackingVE */ SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,'' AS REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_01 p ON od.OD_JOB_NO = p.OD_JOB_NO AND p.POD_STATUS NOT IN ('ECM060','ECM070') LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO' WHERE 1=1 and sm.ETC16 = 'Y'
and (od.HBL_NO = LTRIM(RTRIM(#{hblNo})) or od.OD_JOB_NO IN (SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD_MULTI WHERE DELIVERY_NO = LTRIM(RTRIM(#{hblNo}))))
and od.PO_NO = #{ordId}
UNION ALL
SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,'' AS REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_01 p ON od.MASTER_OD_JOB_NO = p.OD_JOB_NO AND p.POD_STATUS IN ('ECM060','ECM070') LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO' WHERE 1=1 and sm.ETC16 = 'Y'
and (od.HBL_NO = LTRIM(RTRIM(#{hblNo})) or od.OD_JOB_NO IN (SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD_MULTI WHERE DELIVERY_NO = LTRIM(RTRIM(#{hblNo}))))
and od.PO_NO = #{ordId}
UNION ALL
SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,'' AS REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_02 p ON od.OD_JOB_NO = p.OD_JOB_NO LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO' WHERE 1=1 and sm.ETC16 = 'Y'
and (od.HBL_NO = LTRIM(RTRIM(#{hblNo})) or od.OD_JOB_NO IN (SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD_MULTI WHERE DELIVERY_NO = LTRIM(RTRIM(#{hblNo}))))
and od.PO_NO = #{ordId}
UNION ALL
SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME,p.REMARKS,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME, od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_03 p ON od.OD_JOB_NO = p.OD_JOB_NO LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO' WHERE 1=1 and sm.ETC16 = 'Y'
and (od.HBL_NO = LTRIM(RTRIM(#{hblNo})) or od.OD_JOB_NO IN (SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD_MULTI WHERE DELIVERY_NO = LTRIM(RTRIM(#{hblNo}))))
and od.PO_NO = #{ordId}
UNION ALL
SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME , CASE WHEN p.POD_STATUS IN ('ECM361', 'ECM390', 'ECM420') THEN CONCAT(p.DELIVERY_STORE_NAME, '/', p.COURIER_NAME, '/', p.COURIER_TEL) WHEN p.POD_STATUS = 'ECM400' THEN CONCAT(p.DELIVERY_STORE_NAME, '/', p.COURIER_NAME, '/', p.COURIER_TEL, '/', p.REMARKS) ELSE p.REMARKS END AS REMARKS ,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME ,od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_04 p ON od.OD_JOB_NO = p.OD_JOB_NO LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO' WHERE 1=1 and sm.ETC16 = 'Y'
and p.BL_NO = LTRIM(RTRIM(#{hblNo}))
and od.PO_NO = #{ordId}
UNION ALL
SELECT sm.ETC16,od.OD_JOB_NO,p.POD_STATUS,p.POD_NAME,p.POD_DATE,p.POD_TIME , CASE WHEN p.POD_STATUS IN ('ECM361', 'ECM390', 'ECM420') THEN CONCAT(p.DELIVERY_STORE_NAME, '/', p.COURIER_NAME, '/', p.COURIER_TEL) WHEN p.POD_STATUS = 'ECM400' THEN CONCAT(p.DELIVERY_STORE_NAME, '/', p.COURIER_NAME, '/', p.COURIER_TEL, '/', p.REMARKS) ELSE p.REMARKS END AS REMARKS ,od.HBL_NO,od.PO_NO,(CONVERT(VARCHAR, p.POD_DATE, 23) + ' ' + p.POD_TIME) AS TIME ,od.BOUND, od.BOUND_TYPE, sm.NAME_${language} AS TRACKING_CODE_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_POD_04_M p ON od.OD_JOB_NO = p.OD_JOB_NO LEFT JOIN TB_SMS_CODE_DETAIL sm ON p.POD_STATUS = sm.CODE AND sm.GROUP_CODE = 'STATUS_ORDER_CARGO' WHERE 1=1 and sm.ETC16 = 'Y'
and p.BL_NO = LTRIM(RTRIM(#{hblNo}))
and od.PO_NO = #{ordId}

/* interfaceMapper.selectOrderTrackingCustomsInfo */ SELECT od.HBL_NO, od.PO_NO, CASE WHEN DROP_YN = 'Y' THEN 'Withdrawal' WHEN od.CD_TYPE = 'Y' THEN 'Simplified Clearance' WHEN od.CD_TYPE = 'N' THEN 'General Declaration' WHEN od.CD_TYPE = 'B' THEN 'Exclude Simplified Clearance' END AS CUSTOMS_CLEARANCE , CASE WHEN INSPECTION_YN = 'Y' OR ad.SE_INSPECTION_YN = 'Y' THEN 'Inspection' END AS INSPECTION , DROP_CODE AS DROP_CODE , (SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE GROUP_CODE = 'DROP_CODE' AND CODE = DROP_CODE) AS DROP_REASON , od.DELIVERY_CODE
, CASE WHEN (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0 THEN 'Y' ELSE 'N' END AS HOLD_YN , (SELECT TOP 1 HOLD_CODE FROM TB_ECM_OD_HOLD hld WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') AS HOLD_CODE , CASE WHEN ISNULL((SELECT TOP 1 HOLD_CODE FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N'), '') IN ('', '4') THEN (SELECT TOP 1 HOLD_REASON FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') ELSE (SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'HOLD_CODE' AND CODE = (SELECT TOP 1 HOLD_CODE FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N')) END AS HOLD_REASON , ad.WH_LOCATION , (SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE GROUP_CODE = 'WH_LOCATION' AND CODE = WH_LOCATION) AS WH_LOCATION_NAME , CONVERT(CHAR(16), ad.STOCK_DATE_TIME, 20) AS STOCK_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = ad.STOCK_USER_ID) AS STOCK_USER_NAME , ad.WH_CARRYOUT_DATE AS CARRYOUT_DATE , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = ad.CARRYOUT_USER_ID) AS CARRYOUT_USER FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO WHERE 1=1
and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
and od.PO_NO = #{ordId}
and BOUND = #{bound} and BOUND_TYPE = #{boundType}
and od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND PO_NO = #{ordId} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType}

/* interfaceMapper.selectOrderTrackingMultiInfo */ SELECT mul.DELIVERY_NO , mul.DELIVERY_CODE , mul.DELIVERY_NO_CHANGED , mul.SEQ_NO_ID FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_MULTI mul ON od.OD_JOB_NO = mul.OD_JOB_NO WHERE 1=1
and od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
and od.PO_NO = #{ordId}
and BOUND = #{bound} and BOUND_TYPE = #{boundType}
and od.HBL_NO = LTRIM(RTRIM(#{hblNo})) AND PO_NO = #{ordId} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType}

/* interfaceMapper.selectPoNoCnt : PoNo 조회 */
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SELECT 
	   	 COUNT(PO_NO) AS CNT
	FROM TB_ECM_OD
	WHERE PO_NO = #{ordId};

/* interfaceMapper.selectEcmOrderMultiBl */
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SELECT
			od.OD_JOB_NO AS odJobNo
			, od.ENT_CODE AS entCode
			, od.ENT_BUSINESS_CODE AS entBusinessCode
			, od.PO_DATE AS poDate
			, multi.DELIVERY_NO AS deliveryNo
			, multi.DELIVERY_CODE AS deliveryCode
			, od.REGISTER_USER_ID AS userId
	FROM TB_ECM_OD od
	INNER JOIN TB_ECM_OD_MULTI multi
	ON multi.OD_JOB_NO = od.OD_JOB_NO 
	WHERE od.ENT_CODE = #{ReceiverId}
	AND od.OD_JOB_NO = #{odJobNo}
	
	AND multi.DELIVERY_NO = #{hblNo}
